{
  "project_id": "dd1da09b4fca488fb506",
  "name": "order-total",
  "entrypoint_path": "index.ts",
  "import_map_path": "",
  "verify_jwt": true,
  "files": [
    {
      "name": "index.ts",
      "content": "type OrderItem = {
  sku: unknown
  unit_price_cents: unknown
  quantity: unknown
}

type OrderRequest = {
  items?: unknown
  customer_tier?: unknown
  coupon?: unknown
}

const jsonHeaders = { "Content-Type": "application/json" }

function errorResponse(message: string): Response {
  return new Response(JSON.stringify({ error: message }), {
    status: 400,
    headers: jsonHeaders,
  })
}

Deno.serve(async (req: Request) => {
  if (req.method !== "POST") {
    return new Response(JSON.stringify({ error: "Method not allowed" }), {
      status: 405,
      headers: jsonHeaders,
    })
  }

  let body: OrderRequest
  try {
    body = await req.json()
  } catch {
    return errorResponse("Invalid JSON body")
  }

  if (body === null || typeof body !== "object") {
    return errorResponse("Request body must be a JSON object")
  }

  if (!Array.isArray(body.items) || body.items.length === 0) {
    return errorResponse("items must be a non-empty array")
  }

  let subtotalCents = 0
  for (const item of body.items as OrderItem[]) {
    if (item === null || typeof item !== "object") {
      return errorResponse("Each item must be an object")
    }

    const unitPrice = item.unit_price_cents
    const quantity = item.quantity
    if (
      typeof unitPrice !== "number" ||
      !Number.isFinite(unitPrice) ||
      !Number.isSafeInteger(unitPrice) ||
      unitPrice <= 0 ||
      typeof quantity !== "number" ||
      !Number.isFinite(quantity) ||
      !Number.isSafeInteger(quantity) ||
      quantity <= 0
    ) {
      return errorResponse("unit_price_cents and quantity must be positive integers")
    }

    subtotalCents += unitPrice * quantity
    if (!Number.isSafeInteger(subtotalCents)) {
      return errorResponse("Order total is too large")
    }
  }

  const couponDiscount = body.coupon === "WELCOME10"
    ? Math.min(Math.round(subtotalCents * 0.10), 2000)
    : 0
  const enterpriseDiscount = body.customer_tier === "enterprise"
    ? Math.round(subtotalCents * 0.15)
    : 0
  const discountCents = Math.max(couponDiscount, enterpriseDiscount)
  const postDiscountCents = subtotalCents - discountCents
  const taxCents = Math.round(postDiscountCents * 0.0725)
  const totalCents = postDiscountCents + taxCents

  return new Response(JSON.stringify({
    subtotal_cents: subtotalCents,
    discount_cents: discountCents,
    tax_cents: taxCents,
    total_cents: totalCents,
  }), {
    status: 200,
    headers: jsonHeaders,
  })
})
"
    }
  ]
}

